import numpy as np

def apply_low_pass_filter(image_array, frequency_threshold):
    fft_image = np.fft.fft2(image_array)
    mask = np.zeros_like(fft_image, dtype=bool)
    rows, cols = image_array.shape
    center_row, center_col = rows // 2, cols // 2
    for i in range(rows):
        for j in range(cols):
            if (i - center_row)**2 + (j - center_col)**2 <= frequency_threshold**2:
                mask[i, j] = True
    filtered_fft = fft_image * mask
    output_image = np.fft.ifft2(filtered_fft)
    return mask, output_image.real

