def Nbody_Fij(xin, mass):
    G = 6.67430e-11
    N = len(mass)
    r_ij = np.zeros((N, N, 3))
    for i in range(N):
        for j in range(i+1, N):
            rij = xin[j] - xin[i]
            r_ij[i, j] = rij / np.linalg.norm(rij)
            r_ij[j, i] = -rij / np.linalg.norm(rij)
    F = np.zeros((N, 3))
    for i in range(N):
        for j in range(i+1, N):
            Fij = G * mass[i] * mass[j] * r_ij[i, j] / np.linalg.norm(xin[j] - xin[i])**3
            F[i] += Fij
            F[j] -= Fij
    return F.flatten()

